import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No")
        return

    n = int(data[0])
    if n < 4:
        print("No")
        return

    arr = list(map(int, data[1:n+1]))

    # Build a map of sum -> list of pairs of indices
    sum_to_pairs = defaultdict(list)

    for i in range(n):
        for j in range(i+1, n):
            s = arr[i] + arr[j]
            sum_to_pairs[s].append((i, j))

    # For each pair (i,j), check if there's a pair (k,l) with i,j,k,l all distinct
    # such that arr[i] + arr[j] - arr[k] - arr[l] = 1
    # i.e., arr[i] + arr[j] - 1 = arr[k] + arr[l]

    seen = {}
    for i in range(n):
        for j in range(i+1, n):
            target = arr[i] + arr[j] - 1
            if target in sum_to_pairs:
                for k, l in sum_to_pairs[target]:
                    # Check if all four indices are distinct
                    if i != k and i != l and j != k and j != l:
                        print("Yes")
                        return

    print("No")

if __name__ == "__main__":
    main()
